// Storyboard IR — the single input of the production pipeline.
//
// Everything downstream (compile, QC, re-render of one shot) reads this shape.
// It is deliberately plain data: no class instances, no functions, no media
// blobs — so it can be written to disk, diffed, and regenerated by an agent.

export type AspectRatio = '9:16' | '16:9' | '1:1' | '4:5';

export interface StoryboardMeta {
  title: string;
  /** Identifies one production run; also names the work directory. */
  runId: string;
  aspect: AspectRatio;
  width: number;
  height: number;
  fps: number;
  /** Optional pointer to a project DesignStyle; the compiler does not resolve it. */
  styleId?: string;
  language: string;
}

export interface RhythmProfile {
  /** Target average shot length in seconds. */
  avgShotSec: number;
  /** Hard ceiling; a shot longer than this must be split. */
  maxShotSec: number;
  /** How often the visual grammar should change, in seconds. */
  grammarChangeEverySec: number;
  /** How many consecutive shots may reuse the same recipe. */
  maxRepeatRecipe: number;
  /** Ceiling for the opening hook. */
  hookMaxSec: number;
}

export type BeatRole = 'hook' | 'context' | 'point' | 'proof' | 'turn' | 'cta';

export interface Beat {
  id: string;
  role: BeatRole;
  text: string;
  startMs: number;
  endMs: number;
  shotIds: string[];
}

/** Nine-point anchor plus a relative width; resolved to canvas pixels by layout.ts. */
export type Anchor =
  | 'tl' | 'tc' | 'tr'
  | 'ml' | 'mc' | 'mr'
  | 'bl' | 'bc' | 'br'
  | 'full';

export interface LayoutSpec {
  anchor: Anchor;
  /** Element width as a fraction of canvas width (0..1). */
  widthRatio: number;
  /** Extra offset in canvas pixels, applied after the anchor is resolved. */
  offsetX?: number;
  offsetY?: number;
  /** Minimum distance from the canvas edge, in pixels. Default 48. */
  safeInset?: number;
}

/**
 * The graphics over a shot.
 *
 * `mg` is the default path: a named recipe plus parameters. `mg-code` is the
 * escape hatch for shots no recipe covers. Footage is not a visual kind — it is
 * `Shot.underlay`, because a shot can have both and a visual can only be one.
 */
export type VisualSpec =
  | { kind: 'mg'; recipe: string; params: Record<string, unknown>; layout: LayoutSpec }
  | { kind: 'mg-code'; code: string; box: { width: number; height: number }; props?: Record<string, unknown>; layout: LayoutSpec }
  | { kind: 'text'; text: string; fontSize?: number; color?: string; fontWeight?: number; align?: 'left' | 'center' | 'right'; layout: LayoutSpec }
  | { kind: 'solid'; color: string; layout: LayoutSpec };

/**
 * The picture underneath a shot: real footage or a still.
 *
 * A recipe alone is a card. A shot that shows something — a person working, a
 * city at night — needs an image behind the graphics, and that image comes from
 * outside the repo.
 *
 * `query` is the model's search intent; `assetId` is filled in by the footage
 * resolver once a clip has been downloaded into the project pool. Keeping them
 * separate is what makes a storyboard reproducible: the same storyboard always
 * resolves to the same clip, and swapping the source library never invalidates
 * the direction.
 */
export interface UnderlaySpec {
  /** Resolved pool asset. Set by the resolver, never by the model. */
  assetId?: string;
  /** Search intent, in the footage library's language. */
  query?: string;
  /** Why this shot needs footage. Read by QC, not by the compiler. */
  note?: string;
  kind?: 'video' | 'image';
  /** Frames to skip from the source start, so a long clip does not always open on frame 0. */
  srcInFrame?: number;
  /** Cover the frame with a blurred copy behind a contained clip. Set by the resolver. */
  backgroundFill?: boolean;
  /**
   * Whether the footage policy kept this shot.
   *
   * The model proposes a query for most shots; the policy decides how many of
   * those actually become footage, because density is arithmetic, not judgement.
   * A deselected shot keeps its query — raising the density later is then a
   * local re-run rather than another model call.
   */
  selected?: boolean;
  /** The model's own claim that this shot is weak without footage. Always kept. */
  essential?: boolean;
}

export interface Shot {
  /** Stable across recompiles: "S01", "S02", … Never renumber. */
  id: string;
  /** Only meaningful when `beats` is declared; the compiler does not read it. */
  beatId?: string;
  startFrame: number;
  endFrame: number;
  narration: {
    text: string;
    /** Word range into the caption word stream, when one exists. */
    wordRange?: [number, number];
    startMs: number;
    endMs: number;
  };
  /** What the viewer should take away from this shot. Required; drives QC. */
  intent: string;
  /** Graphics over the picture. Optional when `underlay` carries the frame alone. */
  visual?: VisualSpec;
  /** Footage or a still underneath the graphics. */
  underlay?: UnderlaySpec;
  /**
   * Fill the frame behind this shot with a solid colour.
   *
   * A recipe is an overlay — its box is usually smaller than the canvas, so a
   * shot that should read as a full-frame card needs this. The compiler emits a
   * `solid` item underneath and moves the visual to the overlay track. Ignored
   * when `underlay` is present: footage is the background.
   */
  background?: string;
  transitionIn?: { type: string; durationInFrames: number };
}

export interface Storyboard {
  version: 1;
  meta: StoryboardMeta;
  rhythm: RhythmProfile;
  /** Voiceover track. `src` is resolved from the project's asset pool by the caller. */
  audio?: {
    assetId: string;
    src: string;
    durationFrames: number;
    volume?: number;
  };
  /**
   * Background music. Only the mood category is decided here — the track itself
   * is picked from the library by length, so the storyboard stays free of
   * provider ids and stays reproducible when the library grows.
   */
  music?: {
    category: string;
    volume?: number;
    fadeInFrames?: number;
    fadeOutFrames?: number;
  };
  /**
   * Optional narrative grouping. Derivable from the shots' beatIds, so a model
   * does not have to emit it — dropping it cuts a third of the reply and the
   * truncation risk that comes with a long answer.
   */
  beats?: Beat[];
  shots: Shot[];
}

export interface CompileWarning {
  shotId?: string;
  code:
    | 'shot-too-long'
    | 'empty-timeline'
    | 'unsupported-visual'
    | 'asset-missing'
    | 'overlap'
    | 'underlay-unresolved'
    | 'empty-base';
  message: string;
}
